    about = "A log file highlighter",
    long_about = None
)]
struct Args {
    #[arg(short = 'f', long = "follow", help = "Follow the contents of a file")]
    follow: bool,

    #[arg(short = 'p', long = "print", help = "Print the output to stdout")]
    print: bool,

    #[arg(
        long = "config-path",
        value_name = "CONFIG_PATH",
        help = "Provide a custom path to a configuration file"
    )]
    config_path: Option<PathBuf>,

    #[arg(
        short = 'e',
        long = "exec",
        value_name = "EXEC",
        help = "Run command and view the output in a pager"
    )]
    exec: Option<String>,

    #[arg(
        long = "highlight",
        value_name = "COLOR_WORD",
        action = clap::ArgAction::Append,
        help = "Highlights in the form color:word1,word2",
        value_parser = HighlightSpecParser
    )]
    highlights: Vec<CustomHighlight>,

    #[arg(
        long = "enable",
        value_name = "ENABLED_HIGHLIGHTERS",
        value_delimiter = ',',
        action = clap::ArgAction::Append,
        help = "Enable specific highlighters"
    )]
    enable: Vec<HighlightGroup>,

    #[arg(
