def match_bracketed_ipv6(text: str, start: int) -> tuple[int, str] | None:
    if text[start] != "[":
        return None
    end = text.find("]", start + 1)
    if end == -1:
        return None
    candidate = text[start + 1 : end]
    if ":" not in candidate:
        return None
    if not any(ch in "0123456789abcdefABCDEF" for ch in candidate):
